export function estimateCommunityDifficulty(input: ChartDifficultyInput): ChartDifficultyEstimate {
  const feature = chartDifficultyFeatures(input);
  const quality = feature.quality;
  const result: ChartDifficultyEstimate = {
    version: VERSION,
    target: "fc-operation-load",
    estimatedConstant: null,
    components: quality.status === "unavailable" ? null : feature.components,
    quality,
    units: "relative-strain",
    sourceId: input.sourceId,
  };
  if (quality.status === "unavailable") return result;
  const values = [feature.raw.fcSkill ?? NaN, ...KEYS.map((key) => feature.components[key])];
  const outside = CHART_DIFFICULTY_VERSION !== FEATURE_VERSION || values.some(
    (value, i) => !Number.isFinite(value) || value < MIN[i]! || value > MAX[i]!,
  );
  const standardized = values.map((value, i) => (value - MEAN[i]!) / SCALE[i]!);
  const nearest: number[] = [];
  if (!outside) {
    for (const point of POINTS) {
      const distance = Math.sqrt(point.reduce((sum, value, i) => sum + (value - standardized[i]!) ** 2, 0));
      nearest.push(distance);
    }
    nearest.sort((a, b) => a - b);
  }
  if (outside || nearest[4]! > DISTANCE_LIMIT) {
    quality.status = "unavailable";
    quality.confidence = null;
    quality.warnings.push("outside-community-support");
    return result;
  }
  const x = values[0]!;
  let y = CURVE[0]![1]!;
  if (x >= CURVE.at(-1)![0]!) y = CURVE.at(-1)![1]!;
  else if (x > CURVE[0]![0]!) {
    for (let i = 1; i < CURVE.length; i++) {
      const [x0, y0] = CURVE[i - 1]!;
      const [x1, y1] = CURVE[i]!;
      if (x <= x1!) {
        y = y0! + (y1! - y0!) * (x - x0!) / (x1! - x0!);
        break;
      }
    }
  }
  result.estimatedConstant = Math.round(y);
  return result;
}
